// ---------------------------------------------------------------------------
// RENDU -- Direct3D 11, et rien d'autre.
//
// L'ecran de la borne est PLAT : des quadrilateres textures, tries par
// profondeur, avec une echelle et une teinte. Aucune 3D (voir
// analysis/interface_apm3_code.md, section 3.4). Ce module ne fait donc que
// ca, et le fait bien.
//
// TOUT VIENT DE WINDOWS : Direct3D 11 pour dessiner, WIC pour lire les PNG et
// les JPEG, GDI pour graver le texte. Aucune bibliotheque a installer, aucune
// DLL a livrer a cote de l'executable.
//
// LES COORDONNEES sont celles d'un ecran de reference de 1920 x 1080, celui
// de la borne. Le rendu les met a l'echelle de la fenetre reelle. Ainsi les
// constantes lues dans le code de SEGA -- 256, 16, 272, 384 -- gardent leur
// sens quelle que soit la resolution.
// ---------------------------------------------------------------------------
#pragma once
#include <windows.h>
#include <d3d11.h>
#include <string>

namespace rendu {

// L'ecran de reference. Les 256 px d'une icone sont 256 px ici.
const float LARGEUR_REF = 1920.0f;
const float HAUTEUR_REF = 1080.0f;

struct Couleur { float r, v, b, a; };
inline Couleur blanc(float a = 1.0f) { Couleur c = {1, 1, 1, a}; return c; }
inline Couleur noir(float a = 1.0f)  { Couleur c = {0, 0, 0, a}; return c; }

// Une texture prete a dessiner. `large` et `haut` sont ses pixels d'origine.
struct Texture {
    ID3D11ShaderResourceView* vue = nullptr;
    ID3D11Texture2D* surface = nullptr;   // garde pour les textures dynamiques
    int large = 0, haut = 0;
    bool valide() const { return vue != nullptr; }
};

// -- vie du module ----------------------------------------------------------
bool ouvrir(HWND fenetre);
void fermer();
void redimensionner(int large, int haut);

// -- une trame --------------------------------------------------------------
void commencer(Couleur fond);
void presenter();

// Dessine une texture centree sur (cx, cy), de taille (large, haut), le tout
// en coordonnees de l'ecran de reference. `teinte` multiplie la couleur : du
// blanc laisse l'image intacte, du noir en fait une ombre.
void quad(const Texture& t, float cx, float cy, float large, float haut,
          Couleur teinte);

// Un rectangle plein, sans texture.
void rectangle(float cx, float cy, float large, float haut, Couleur c);

// -- les images -------------------------------------------------------------
// Lit un PNG, un JPEG, un BMP... par WIC. Rend une texture invalide si le
// fichier manque ou n'est pas une image.
Texture charger_image(const std::wstring& chemin);

// Une texture que l'on remplit trame apres trame -- pour la video.
Texture creer_dynamique(int large, int haut);
void ecrire_dynamique(Texture& t, const void* pixels, int pas_octets);

void liberer(Texture& t);

// -- le texte ---------------------------------------------------------------
// Grave une chaine dans une texture, par GDI. C'est fait une fois par titre,
// pas a chaque trame : un titre ne change que lorsque la selection change.
//
// Pourquoi GDI et pas DirectWrite : le texte est grave EN BLANC SUR NOIR, et
// la luminance devient la transparence. C'est exact pour du texte clair, ca
// ne demande aucune interoperation entre Direct2D et Direct3D, et ca ne peut
// pas echouer a l'execution.
Texture graver_texte(const std::wstring& texte, int corps, bool gras);

} // namespace rendu

