// Ce que le nuanceur recoit. Aligne sur 16 octets, comme Direct3D l'exige.
struct Constantes {
    float rect[4];      // centre x, centre y, demi-largeur, demi-hauteur
    float teinte[4];
    float ecran[4];     // largeur et hauteur de reference
};

// Un quadrilatere sans tampon de sommets : les quatre coins sont calcules
// dans le nuanceur a partir du numero de sommet. Moins d'etat, moins de code.
const char* NUANCEURS = R"(
cbuffer CB : register(b0) {
    float4 rect;      // cx, cy, demi-largeur, demi-hauteur
    float4 teinte;
    float4 ecran;     // largeur, hauteur
