struct Sortie { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

Sortie VS(uint id : SV_VertexID) {
    float2 coin = float2((id == 1 || id == 3) ? 1.0 : -1.0,
                         (id == 2 || id == 3) ? 1.0 : -1.0);
    float2 px = rect.xy + coin * rect.zw;          // pixels de reference
    Sortie s;
    // Origine en haut a gauche, y vers le bas -> repere de Direct3D.
    s.pos = float4(px.x / ecran.x * 2.0 - 1.0,
                   1.0 - px.y / ecran.y * 2.0, 0.0, 1.0);
    s.uv  = float2(coin.x * 0.5 + 0.5, coin.y * 0.5 + 0.5);
    return s;
}

Texture2D image : register(t0);
SamplerState ech : register(s0);

float4 PS(Sortie s) : SV_TARGET {
    return image.Sample(ech, s.uv) * teinte;
}
float4 PS_plein(Sortie s) : SV_TARGET {
    return teinte;
}
