// ---------------------------------------------------------------------------
// CATALOGUE -- la liste des jeux, lue sur le disque.
//
// La borne d'origine demande sa liste au demon `amdaemon`, par le reseau
// (AppImage_getOptionMountRootPath, AppImage_makeOptionMountPath). Ici on lit
// UN DOSSIER, et c'est la seule difference de fond avec l'original.
//
//     borne\jeux\<un dossier par jeu>\
//         jaquette.png    carree, 512 conseille, 384 minimum
//         demo.mp4        H.264, facultative
//         jeu.json        facultatif : titre, exe, args, editeur, annee
//
// L'EXECUTABLE EST FACULTATIF. Sans lui, le jeu reste dans la vitrine et son
// lancement joue l'animation puis revient. Ce n'est pas une invention : c'est
// le mode `bootApplication = false` que SEGA a laisse dans son propre code
// (SceneManager.GameStart, et le retour par CancelStartGame dans Update).
// ---------------------------------------------------------------------------
#pragma once
#include <string>
#include <vector>

namespace catalogue {

struct Jeu {
    std::wstring id;          // le nom du dossier
    std::wstring titre;
    std::wstring editeur;
    std::wstring annee;
    std::wstring jaquette;    // chemin complet, vide si absente
    std::wstring demo;        // chemin complet, vide si absente
    std::wstring exe;         // chemin complet, vide = mode vitrine
    std::vector<std::wstring> args;
    bool lancable() const { return !exe.empty(); }
};

// Lit le dossier. Rend les jeux tries par nom de dossier.
std::vector<Jeu> lire(const std::wstring& dossier_jeux);

// Demarre l'executable d'un jeu. Rend false si le jeu n'en a pas, ou si
// Windows refuse. `message` dit pourquoi.
bool lancer(const Jeu& j, std::wstring& message);

} // namespace catalogue

