// ---------------------------------------------------------------------------
// CATALOGUE -- mise en oeuvre. Voir catalogue.h.
// ---------------------------------------------------------------------------
#include "catalogue.h"
#include <windows.h>
#include <shellapi.h>
#include <algorithm>
#include <string>
#include <vector>

namespace catalogue {
namespace {

bool finit_par(const std::wstring& s, const std::wstring& fin) {
    if (s.size() < fin.size()) return false;
    std::wstring q = s.substr(s.size() - fin.size());
    std::transform(q.begin(), q.end(), q.begin(), ::towlower);
    return q == fin;
}

bool existe(const std::wstring& c) {
    DWORD a = GetFileAttributesW(c.c_str());
    return a != INVALID_FILE_ATTRIBUTES && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

std::string lire_fichier(const std::wstring& chemin) {
    HANDLE h = CreateFileW(chemin.c_str(), GENERIC_READ, FILE_SHARE_READ,
                           nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL,
                           nullptr);
    if (h == INVALID_HANDLE_VALUE) return std::string();
    LARGE_INTEGER taille;
    if (!GetFileSizeEx(h, &taille) || taille.QuadPart > (1 << 20)) {
        CloseHandle(h); return std::string();
    }
    std::string d((size_t)taille.QuadPart, '\0');
    DWORD lus = 0;
    ReadFile(h, &d[0], (DWORD)d.size(), &lus, nullptr);
    CloseHandle(h);
    d.resize(lus);
    return d;
}

std::wstring vers_large(const std::string& utf8) {
    if (utf8.empty()) return std::wstring();
    int n = MultiByteToWideChar(CP_UTF8, 0, utf8.c_str(), (int)utf8.size(),
                                nullptr, 0);
    std::wstring s((size_t)n, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, utf8.c_str(), (int)utf8.size(), &s[0], n);
    return s;
}

// -- un lecteur de JSON juste assez grand pour `jeu.json` --------------------
//
// Le fichier n'a qu'un niveau : des chaines, des nombres, et un tableau de
// chaines pour `args`. Ecrire un analyseur complet serait du travail perdu ;
// celui-ci saute les blancs, lit les chaines avec leurs echappements, et
// ignore ce qu'il ne comprend pas plutot que de refuser le fichier.

struct Lecteur {
    const std::string& s;
    size_t i = 0;
    explicit Lecteur(const std::string& t) : s(t) {}

    void blancs() {
        while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\r' ||
                                s[i] == '\n'))
            ++i;
    }
    bool chaine(std::string& sortie) {
        blancs();
        if (i >= s.size() || s[i] != '"') return false;
        ++i;
        sortie.clear();
        while (i < s.size() && s[i] != '"') {
            if (s[i] == '\\' && i + 1 < s.size()) {
                ++i;
                char c = s[i];
                if (c == 'n') sortie += '\n';
                else if (c == 't') sortie += '\t';
                else if (c == 'u') {   // on garde le caractere brut, sans BMP
                    i += 4;            // suffisant pour un chemin Windows
                } else sortie += c;    // \\ et \" tombent ici, c'est voulu
            } else {
                sortie += s[i];
            }
            ++i;
        }
        if (i < s.size()) ++i;
        return true;
    }
    // Lit une valeur brute (nombre, mot-cle) jusqu'a la virgule ou l'accolade.
    std::string brut() {
        blancs();
        size_t debut = i;
        int profondeur = 0;
        while (i < s.size()) {
            char c = s[i];
            if (c == '[' || c == '{') ++profondeur;
            else if (c == ']' || c == '}') {
                if (profondeur == 0) break;
                --profondeur;
            } else if (c == ',' && profondeur == 0) break;
            ++i;
        }
        return s.substr(debut, i - debut);
    }
};

void lire_json(const std::string& texte, Jeu& j) {
    Lecteur l(texte);
    l.blancs();
    if (l.i < texte.size() && texte[l.i] == '{') ++l.i;
    while (l.i < texte.size()) {
        l.blancs();
        if (l.i >= texte.size() || texte[l.i] == '}') break;
        std::string cle;
        if (!l.chaine(cle)) { ++l.i; continue; }
        l.blancs();
        if (l.i < texte.size() && texte[l.i] == ':') ++l.i;
        l.blancs();

        if (cle == "args") {
            // Un tableau de chaines.
            if (l.i < texte.size() && texte[l.i] == '[') {
                ++l.i;
                std::string v;
                while (l.i < texte.size()) {
                    l.blancs();
                    if (l.i < texte.size() && texte[l.i] == ']') { ++l.i; break; }
                    if (l.chaine(v)) j.args.push_back(vers_large(v));
                    else ++l.i;
                    l.blancs();
                    if (l.i < texte.size() && texte[l.i] == ',') ++l.i;
                }
            } else {
                l.brut();
            }
        } else if (l.i < texte.size() && texte[l.i] == '"') {
            std::string v;
            l.chaine(v);
            std::wstring w = vers_large(v);
            if (cle == "titre") j.titre = w;
            else if (cle == "exe") j.exe = w;
            else if (cle == "editeur") j.editeur = w;
            else if (cle == "annee") j.annee = w;
        } else {
            std::string v = l.brut();
            // Un nombre nu : on le garde tel quel, c'est du texte a l'ecran.
            while (!v.empty() && (v.back() == ' ' || v.back() == '\n' ||
                                  v.back() == '\r' || v.back() == '\t'))
                v.pop_back();
            if (cle == "annee") j.annee = vers_large(v);
        }
        l.blancs();
        if (l.i < texte.size() && texte[l.i] == ',') ++l.i;
    }
}

// Cherche `base` + une des extensions, dans l'ordre donne.
std::wstring cherche(const std::wstring& dossier, const wchar_t* base,
                     const std::vector<std::wstring>& exts) {
    for (const std::wstring& e : exts) {
        std::wstring c = dossier + L"\\" + base + e;
        if (existe(c)) return c;
    }
    return std::wstring();
}

// Le premier fichier du dossier dont l'extension est dans la liste.
std::wstring premier_de(const std::wstring& dossier,
                        const std::vector<std::wstring>& exts) {
    WIN32_FIND_DATAW fd;
    HANDLE h = FindFirstFileW((dossier + L"\\*").c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return std::wstring();
    std::vector<std::wstring> trouves;
    do {
        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;
        std::wstring n = fd.cFileName;
        if (!n.empty() && n[0] == L'_') continue;      // _source_*, ignores
        for (const std::wstring& e : exts)
            if (finit_par(n, e)) { trouves.push_back(n); break; }
    } while (FindNextFileW(h, &fd));
    FindClose(h);
    if (trouves.empty()) return std::wstring();
    std::sort(trouves.begin(), trouves.end());
    return dossier + L"\\" + trouves.front();
}

} // namespace anonyme

std::vector<Jeu> lire(const std::wstring& dossier_jeux) {
    std::vector<Jeu> jeux;
    WIN32_FIND_DATAW fd;
    HANDLE h = FindFirstFileW((dossier_jeux + L"\\*").c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return jeux;

    std::vector<std::wstring> noms;
    do {
        if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) continue;
        std::wstring n = fd.cFileName;
        if (n == L"." || n == L"..") continue;
        noms.push_back(n);
    } while (FindNextFileW(h, &fd));
    FindClose(h);
    std::sort(noms.begin(), noms.end());

    const std::vector<std::wstring> IMAGES = {L".png", L".jpg", L".jpeg",
                                              L".bmp"};
    const std::vector<std::wstring> VIDEOS = {L".mp4", L".m4v", L".mov",
                                              L".wmv", L".avi", L".mkv"};
    const std::vector<std::wstring> EXES = {L".exe", L".cmd", L".bat",
                                            L".lnk"};

    for (const std::wstring& n : noms) {
        std::wstring d = dossier_jeux + L"\\" + n;
        Jeu j;
        j.id = n;
        j.titre = n;

        std::string js = lire_fichier(d + L"\\jeu.json");
        if (!js.empty()) lire_json(js, j);
        if (j.titre.empty()) j.titre = n;

        j.jaquette = cherche(d, L"jaquette", IMAGES);
        if (j.jaquette.empty()) j.jaquette = premier_de(d, IMAGES);
        j.demo = cherche(d, L"demo", VIDEOS);
        if (j.demo.empty()) j.demo = premier_de(d, VIDEOS);

        if (!j.exe.empty() && !existe(j.exe)) {
            // Un chemin relatif au dossier du jeu est accepte.
            std::wstring relatif = d + L"\\" + j.exe;
            j.exe = existe(relatif) ? relatif : std::wstring();
        }
        if (j.exe.empty()) j.exe = premier_de(d, EXES);

        jeux.push_back(j);
    }
    return jeux;
}

bool lancer(const Jeu& j, std::wstring& message) {
    if (j.exe.empty()) {
        message = L"pas d'executable -- vitrine";
        return false;
    }
    std::wstring parametres;
    for (size_t i = 0; i < j.args.size(); ++i) {
        if (i) parametres += L" ";
        // Un argument qui contient une espace se met entre guillemets.
        if (j.args[i].find(L' ') != std::wstring::npos)
            parametres += L"\"" + j.args[i] + L"\"";
        else
            parametres += j.args[i];
    }
    std::wstring dossier = j.exe;
    size_t barre = dossier.find_last_of(L'\\');
    if (barre != std::wstring::npos) dossier.resize(barre);

    SHELLEXECUTEINFOW info = {};
    info.cbSize = sizeof(info);
    info.fMask = SEE_MASK_NOASYNC;
    info.lpVerb = L"open";
    info.lpFile = j.exe.c_str();
    info.lpParameters = parametres.empty() ? nullptr : parametres.c_str();
    info.lpDirectory = dossier.c_str();
    info.nShow = SW_SHOWNORMAL;
    if (ShellExecuteExW(&info)) {
        if (info.hProcess) CloseHandle(info.hProcess);
        message = j.titre;
        return true;
    }
    message = L"Windows a refuse de lancer " + j.exe;
    return false;
}

} // namespace catalogue

