// ---------------------------------------------------------------------------
// VIDEO -- Media Foundation, le lecteur video de Windows.
//
// La borne d'origine emploie AVPro Video, un greffon Unity qui, sur Windows,
// s'appuie lui-meme sur Media Foundation. On va donc directement a la source :
// aucun codec a installer, aucune DLL a livrer.
//
// C'est aussi ce qui fixe le format demande aux videos : H.264 dans un .mp4.
// Media Foundation le decode d'office. Le H.265 demande sur Windows 11 un
// codec PAYANT -- d'ou son refus par tools/jeux.py.
//
// PAS DE SON pour l'instant : dans l'original, la demonstration en attract
// est muette par defaut (EnableAdvertizeSound). On decode donc l'image seule.
// ---------------------------------------------------------------------------
#pragma once
#include "rendu.h"
#include <string>

struct IMFSourceReader;

class Video {
public:
    ~Video();

    // Ouvre un fichier. Rend false sans bruit si le format est refuse : la
    // vitrine doit continuer de tourner meme avec une video illisible.
    bool ouvrir(const std::wstring& chemin);
    void fermer();

    // Fait avancer la lecture de `dt` secondes et met la texture a jour.
    // Rend false quand la video est finie et ne boucle pas.
    bool avancer(double dt);

    bool ouverte() const { return lecteur_ != nullptr; }
    const rendu::Texture& image() const { return texture_; }
    int large() const { return large_; }
    int haut() const { return haut_; }
    void reprendre_au_debut();

    bool boucler = true;

private:
    IMFSourceReader* lecteur_ = nullptr;
    rendu::Texture texture_;
    int large_ = 0, haut_ = 0;
    int pas_ = 0;              // octets par ligne, negatif si image renversee
    double horloge_ = 0.0;     // secondes ecoulees depuis le debut
    double prochaine_ = 0.0;   // date de la trame suivante
    bool finie_ = false;
};

// A appeler une fois au demarrage du programme, et une fois a la fin.
bool video_ouvrir_module();
void video_fermer_module();

