// ---------------------------------------------------------------------------
// LA BORNE -- l'interface, en C++.
//
// Portage de l'ecran de choix des jeux de l'ALL.Net P-ras Multi version 3.
// Le carrousel et la machine a etats ne sont pas imites : ils sont TRANSCRITS
// depuis le code de SEGA, decompile dans analysis/apm3_source/ et decrit dans
// analysis/interface_apm3_code.md.
//
// Ce qui vient tel quel de `Apm.System.GameSelect.IconListCanvas` :
//
//     accel = -1        la deceleration, en pixels par trame et par trame
//     iconSize = 256    le cote d'une icone
//     gapSize = 16      l'ecart entre deux icones, donc un pas de 272
//     selectedIconRatio = 1.5    l'agrandissement de l'icone du centre
//     rangeOfMovement = 0.5      la butee, a 128 px
//     conditionSpeed             resolu comme dans Awake : 24
//
// Et le mouvement lui-meme -- Select, IntertialMove, AlignmentIcon, Sort,
// GetNextSelectIcon -- ligne pour ligne.
//
// Ce qui change, et c'est tout : la liste des jeux vient d'un DOSSIER et non
// du demon `amdaemon`. Rien d'autre n'a ete simplifie.
// ---------------------------------------------------------------------------
#include "rendu.h"
#include "catalogue.h"
#include "video.h"
#include <windows.h>
#include <xinput.h>
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>

// ---------------------------------------------------------------------------
// Les constantes de SEGA. Ne pas les ajuster a l'oeil : elles sont lues.
// ---------------------------------------------------------------------------
const float ACCEL = 1.0f;         // |accel.x|
const float TAILLE_ICONE = 256.0f;
const float ECART = 16.0f;
const float PAS = TAILLE_ICONE + ECART;          // 272
const float RATIO_SELECTION = 1.5f;
const float PORTEE_MOUVEMENT = 0.5f;             // butee a 128 px
const float OMBRE_Z_CENTRE = -24.0f;
const float OMBRE_Z = -16.0f;

// La borne tourne a 60 images par seconde, et `speed` est en pixels PAR
// TRAME. On avance donc la logique par pas fixes de 1/60 s, quelle que soit
// la cadence reelle de l'ecran : sinon le ressenti changerait avec le moniteur.
const double PAS_LOGIQUE = 1.0 / 60.0;

// La mise en page, sur l'ecran de reference de 1920 x 1080.
const float BANDE_HAUT = 96.0f;
const float BANDE_BAS = 88.0f;
const float Y_ICONES = 500.0f;
const float Y_TITRE = 762.0f;
const float Y_SOUS = 818.0f;
const float Y_MESSAGE = 906.0f;

const double ATTRACT_DEFAUT = 30.0;   // advertizeTime, en secondes

// ---------------------------------------------------------------------------
namespace {

struct Icone {
    catalogue::Jeu jeu;
    rendu::Texture jaquette;
    rendu::Texture titre;
    rendu::Texture sous;
    float x = 0.0f;               // anchoredPosition.x
};

std::vector<Icone> g_icones;
int g_index = 0;
float g_vitesse = 0.0f;
float g_condition_vitesse = 24.0f;
bool g_en_mouvement = false;
bool g_inertie = false;

// L'etat de scene, transcrit de GameSelect.SceneManager.
enum class Etat { Choix, Lancement, Retour };
Etat g_etat = Etat::Choix;
double g_anim = 0.0;              // avancement de l'animation en cours
double g_ecoule = 0.0;            // elapsedTime
double g_attract = ATTRACT_DEFAUT;
bool g_en_attract = false;
std::wstring g_message;
double g_message_reste = 0.0;

Video g_video;
bool g_video_visible = false;

rendu::Texture g_txt_aide;
rendu::Texture g_txt_vide;
rendu::Texture g_txt_message;
std::wstring g_message_grave;

HWND g_fenetre = nullptr;
std::wstring g_dossier_jeux;
bool g_plein_ecran = false;
RECT g_avant_plein = {};

// XInput est charge a la demande : ainsi le programme demarre meme si la DLL
// manque, et il n'y a rien a lier a la compilation.
typedef DWORD (WINAPI* PFN_XInputGetState)(DWORD, XINPUT_STATE*);
PFN_XInputGetState g_xinput = nullptr;
WORD g_boutons_avant = 0;
SHORT g_axe_avant = 0;

// ---------------------------------------------------------------------------
// Le carrousel. Transcription de IconListCanvas.
// ---------------------------------------------------------------------------

// Le meme calcul que Select() et que Awake() : on cherche la plus petite
// vitesse entiere telle que 1 + 2 + ... + n couvre la distance. C'est une
// somme triangulaire, et c'est ce qui fait qu'une icone s'arrete PILE au
// centre sans etre rattrapee par une interpolation.
float resoudre_vitesse(float distance) {
    float vitesse = ACCEL;
    float parcouru = 0.0f;
    int garde = 100000;
    while (parcouru < distance && garde-- > 0) {
        parcouru += vitesse;
        vitesse += ACCEL;
    }
    return vitesse;
}

void aligner(int selection, float decalage = 0.0f) {
    for (size_t i = 0; i < g_icones.size(); ++i)
        g_icones[i].x = -PAS * (float)(selection - (int)i) + decalage;
    g_vitesse = 0.0f;
}

void selectionner(int cible) {
    if (g_icones.empty()) return;
    cible = std::max(0, std::min((int)g_icones.size() - 1, cible));
    float x = g_icones[cible].x;
    float v = resoudre_vitesse(std::fabs(x));
    g_vitesse = (x > 0.0f) ? -v : v;
    g_index = cible;
    g_en_mouvement = true;
}

// GetNextSelectIcon : selon le sens, l'icone la plus proche du centre du bon
// cote -- celle qui va y arriver.
int prochaine_selection() {
    if (g_icones.empty()) return 0;
    int choix;
    if (g_vitesse > 0.0f) {
        choix = 0;
        for (size_t i = 0; i < g_icones.size(); ++i)
            if (g_icones[choix].x < g_icones[i].x && g_icones[i].x <= 0.0f)
                choix = (int)i;
    } else {
        choix = (int)g_icones.size() - 1;
        for (size_t i = 0; i < g_icones.size(); ++i)
            if (g_icones[choix].x > g_icones[i].x && g_icones[i].x >= 0.0f)
                choix = (int)i;
    }
    return choix;
}

// IntertialMove, ligne pour ligne.
void mouvement_inertiel() {
    if (g_icones.empty()) return;
    for (Icone& ic : g_icones) ic.x += g_vitesse;

    float reste = std::fabs(g_vitesse) - ACCEL;
    if (reste < 0.0f) g_vitesse = 0.0f;
    else g_vitesse = (g_vitesse > 0.0f) ? reste : -reste;

    if (std::fabs(g_vitesse) >= std::fabs(g_condition_vitesse)) {
        // Encore lance : on ne laisse pas la liste sortir de ses bornes.
        float butee = TAILLE_ICONE * PORTEE_MOUVEMENT;      // 128
        if (g_icones.front().x >= butee) {
            aligner(0, butee);
            selectionner(0);
        } else if (g_icones.back().x <= -butee) {
            aligner((int)g_icones.size() - 1, -butee);
            selectionner((int)g_icones.size() - 1);
        }
        return;
    }
    if (g_inertie) {
        selectionner(prochaine_selection());
        g_inertie = false;
    }
    float xs = g_icones[g_index].x;
    if ((g_vitesse > 0.0f && xs > 0.0f) ||
        (g_vitesse < 0.0f && xs < 0.0f) ||
        (g_vitesse == 0.0f && xs != 0.0f)) {
        aligner(g_index);
        g_en_mouvement = false;
    }
}

bool peut_bouger() { return g_etat == Etat::Choix && !g_video_visible; }
bool peut_choisir() { return peut_bouger() && !g_en_mouvement; }

void aller_gauche() {
    if (!peut_bouger() || g_icones.empty()) return;
    g_vitesse = -(g_condition_vitesse + ACCEL);   // conditionSpeed - accel
    g_inertie = true;
    g_index = prochaine_selection();
    g_en_mouvement = true;
}

void aller_droite() {
    if (!peut_bouger() || g_icones.empty()) return;
    g_vitesse = g_condition_vitesse + ACCEL;
    g_inertie = true;
    g_index = prochaine_selection();
    g_en_mouvement = true;
}

void suivant() {   // MoveNext : ce que l'attract appelle entre deux videos
    if (!peut_choisir() || g_icones.empty()) return;
    selectionner((g_index + 1 < (int)g_icones.size()) ? g_index + 1 : 0);
}

// ---------------------------------------------------------------------------
// Le catalogue
// ---------------------------------------------------------------------------
void message(const std::wstring& texte, double duree = 3.0) {
    g_message = texte;
    g_message_reste = duree;
}

void liberer_icones() {
    for (Icone& ic : g_icones) {
        rendu::liberer(ic.jaquette);
        rendu::liberer(ic.titre);
        rendu::liberer(ic.sous);
    }
    g_icones.clear();
}

void charger_catalogue() {
    std::wstring garde_id;
    if (g_index >= 0 && g_index < (int)g_icones.size())
        garde_id = g_icones[g_index].jeu.id;

    liberer_icones();
    std::vector<catalogue::Jeu> jeux = catalogue::lire(g_dossier_jeux);
    for (const catalogue::Jeu& j : jeux) {
        Icone ic;
        ic.jeu = j;
        if (!j.jaquette.empty()) ic.jaquette = rendu::charger_image(j.jaquette);
        ic.titre = rendu::graver_texte(j.titre, 44, true);
        std::wstring sous = j.editeur;
        if (!j.annee.empty()) sous += (sous.empty() ? L"" : L"   ") + j.annee;
        if (!j.lancable())
            sous += (sous.empty() ? L"" : L"      ") + std::wstring(L"vitrine");
        if (!sous.empty()) ic.sous = rendu::graver_texte(sous, 26, false);
        g_icones.push_back(ic);
    }

    g_index = 0;
    for (size_t i = 0; i < g_icones.size(); ++i)
        if (g_icones[i].jeu.id == garde_id) g_index = (int)i;

    // conditionSpeed, resolu comme dans Awake : la vitesse qui couvre
    // exactement une icone. Avec accel = 1 et iconSize = 256, cela donne 24.
    g_condition_vitesse = resoudre_vitesse(TAILLE_ICONE);
    g_vitesse = 0.0f;
    g_en_mouvement = false;
    g_inertie = false;
    aligner(g_index);
}

// ---------------------------------------------------------------------------
// La machine a etats : GameStart, puis le retour par CancelStartGame.
// ---------------------------------------------------------------------------
void arreter_video() {
    if (!g_video_visible) return;
    g_video.fermer();
    g_video_visible = false;
    g_en_attract = false;
}

void jouer_video() {
    if (g_icones.empty()) return;
    const std::wstring& chemin = g_icones[g_index].jeu.demo;
    if (chemin.empty()) return;
    if (g_video.ouvrir(chemin)) {
        g_video.boucler = false;      // en attract on passe au jeu suivant
        g_video_visible = true;
    }
}

void remettre_a_zero_ecoule() {
    if (g_en_attract) arreter_video();
    g_ecoule = 0.0;
    g_en_attract = false;
}

void demarrer() {
    if (!peut_choisir() || g_icones.empty()) return;
    g_etat = Etat::Lancement;
    g_anim = 0.0;
    remettre_a_zero_ecoule();
}

void entree_quelconque() {
    // Le motif constant de SceneManager : toute entree annule la demonstration
    // et remet le compteur d'attract a zero.
    remettre_a_zero_ecoule();
}

// ---------------------------------------------------------------------------
// Le dessin
// ---------------------------------------------------------------------------
struct Ordre { int i; float distance; };

void dessiner() {
    rendu::Couleur fond = {0.043f, 0.051f, 0.070f, 1.0f};
    rendu::commencer(fond);

    const float CX = rendu::LARGEUR_REF * 0.5f;

    // -- les icones, les plus lointaines d'abord (Sort) ----------------------
    std::vector<Ordre> ordre;
    for (size_t i = 0; i < g_icones.size(); ++i) {
        Ordre o; o.i = (int)i; o.distance = std::fabs(g_icones[i].x);
        ordre.push_back(o);
    }
    std::sort(ordre.begin(), ordre.end(),
              [](const Ordre& a, const Ordre& b) {
                  return a.distance > b.distance;   // loin dessine en premier
              });

    // Le fondu de l'animation de lancement.
    float clarte = 1.0f;
    if (g_etat == Etat::Lancement) clarte = 1.0f - (float)std::min(1.0, g_anim / 0.45);
    else if (g_etat == Etat::Retour) clarte = (float)std::min(1.0, g_anim / 0.45);

    for (const Ordre& o : ordre) {
        const Icone& ic = g_icones[o.i];
        float ax = std::fabs(ic.x);

        // IconCanvas, lignes 116-124 : une rampe LINEAIRE, pas une courbe.
        float demi = TAILLE_ICONE * RATIO_SELECTION * 0.5f;      // 192
        float echelle = (ax >= demi)
                ? 1.0f
                : (1.0f - RATIO_SELECTION) / demi * ax + RATIO_SELECTION;
        float z = OMBRE_Z - ((ax >= demi)
                ? 0.0f
                : (OMBRE_Z_CENTRE - OMBRE_Z) / demi * ax
                  - (OMBRE_Z_CENTRE - OMBRE_Z));

        float cote = TAILLE_ICONE * echelle;
        float x = CX + ic.x;

        // L'ombre : l'original deplace un enfant en Z. Sur un ecran plat, cette
        // profondeur devient un decalage et une opacite -- c'est la seule
        // interpretation de tout le portage, et elle est ici, en clair.
        float profondeur = std::fabs(z) - std::fabs(OMBRE_Z);    // 0 a 8
        float decalage = profondeur * 1.6f;
        float opacite = (0.34f + profondeur * 0.028f) * clarte;
        rendu::rectangle(x + decalage * 0.35f, Y_ICONES + decalage,
                         cote * 1.02f, cote * 1.02f,
                         rendu::Couleur{0, 0, 0, opacite});

        if (ic.jaquette.valide()) {
            rendu::Couleur t = rendu::blanc(clarte);
            if (!ic.jeu.lancable()) { t.r *= 0.88f; t.v *= 0.90f; t.b *= 0.94f; }
            rendu::quad(ic.jaquette, x, Y_ICONES, cote, cote, t);
        } else {
            rendu::rectangle(x, Y_ICONES, cote, cote,
                             rendu::Couleur{0.09f, 0.11f, 0.14f, clarte});
        }
    }

    // -- le titre, seulement quand la selection est stable -------------------
    if (peut_choisir() && !g_icones.empty()) {
        const Icone& ic = g_icones[g_index];
        if (ic.titre.valide())
            rendu::quad(ic.titre, CX, Y_TITRE, (float)ic.titre.large,
                        (float)ic.titre.haut, rendu::blanc(clarte));
        if (ic.sous.valide())
            rendu::quad(ic.sous, CX, Y_SOUS, (float)ic.sous.large,
                        (float)ic.sous.haut,
                        rendu::Couleur{0.52f, 0.57f, 0.64f, clarte});
    }

    // -- la video de demonstration, par-dessus -------------------------------
    if (g_video_visible && g_video.image().valide()) {
        rendu::rectangle(CX, rendu::HAUTEUR_REF * 0.5f, rendu::LARGEUR_REF,
                         rendu::HAUTEUR_REF, rendu::Couleur{0, 0, 0, 0.82f});
        float dispo_l = 1440.0f, dispo_h = 810.0f;
        float rl = dispo_l / (float)g_video.large();
        float rh = dispo_h / (float)g_video.haut();
        float r = rl < rh ? rl : rh;
        rendu::quad(g_video.image(), CX, rendu::HAUTEUR_REF * 0.5f,
                    g_video.large() * r, g_video.haut() * r, rendu::blanc());
    }

    // -- les bandeaux --------------------------------------------------------
    rendu::rectangle(CX, BANDE_HAUT * 0.5f, rendu::LARGEUR_REF, BANDE_HAUT,
                     rendu::Couleur{0, 0, 0, 1});
    rendu::rectangle(CX, BANDE_HAUT, rendu::LARGEUR_REF, 2.0f,
                     rendu::Couleur{0.16f, 0.19f, 0.25f, 1});
    rendu::rectangle(CX, rendu::HAUTEUR_REF - BANDE_BAS * 0.5f,
                     rendu::LARGEUR_REF, BANDE_BAS,
                     rendu::Couleur{0, 0, 0, 1});
    rendu::rectangle(CX, rendu::HAUTEUR_REF - BANDE_BAS, rendu::LARGEUR_REF,
                     2.0f, rendu::Couleur{0.16f, 0.19f, 0.25f, 1});

    if (g_txt_aide.valide())
        rendu::quad(g_txt_aide, CX, rendu::HAUTEUR_REF - BANDE_BAS * 0.5f,
                    (float)g_txt_aide.large, (float)g_txt_aide.haut,
                    rendu::Couleur{0.49f, 0.54f, 0.62f, 1});

    if (g_icones.empty() && g_txt_vide.valide())
        rendu::quad(g_txt_vide, CX, rendu::HAUTEUR_REF * 0.5f,
                    (float)g_txt_vide.large, (float)g_txt_vide.haut,
                    rendu::Couleur{0.52f, 0.57f, 0.64f, 1});

    if (g_message_reste > 0.0 && g_txt_message.valide()) {
        float a = (float)std::min(1.0, g_message_reste / 0.4);
        rendu::rectangle(CX, Y_MESSAGE, (float)g_txt_message.large + 56.0f,
                         (float)g_txt_message.haut + 26.0f,
                         rendu::Couleur{0, 0, 0, 0.80f * a});
        rendu::quad(g_txt_message, CX, Y_MESSAGE,
                    (float)g_txt_message.large, (float)g_txt_message.haut,
                    rendu::blanc(a));
    }

    rendu::presenter();
}

// ---------------------------------------------------------------------------
// Une trame de logique
// ---------------------------------------------------------------------------
void avancer(double dt) {
    if (g_message_reste > 0.0) g_message_reste -= dt;
    if (!g_message.empty() && g_message != g_message_grave) {
        rendu::liberer(g_txt_message);
        g_txt_message = rendu::graver_texte(g_message, 30, false);
        g_message_grave = g_message;
    }

    // Le carrousel avance par pas fixes de 1/60 s : `speed` est en pixels par
    // trame dans le code d'origine, pas en pixels par seconde.
    static double reste = 0.0;
    reste += dt;
    int garde = 8;
    while (reste >= PAS_LOGIQUE && garde-- > 0) {
        reste -= PAS_LOGIQUE;
        if (g_vitesse != 0.0f) mouvement_inertiel();
    }
    if (reste > 0.5) reste = 0.0;

    switch (g_etat) {
    case Etat::Choix:
        // UpdateElapsedTime : on detecte le FRANCHISSEMENT du seuil.
        if (peut_choisir() && !g_icones.empty() && !g_en_attract) {
            bool avant = (g_ecoule >= g_attract);
            g_ecoule += dt;
            if (!avant && g_ecoule >= g_attract) {
                g_en_attract = true;
                jouer_video();
                if (!g_video_visible) {      // pas de video : on passe au jeu
                    suivant();               // suivant, comme WaitCanMove
                    g_ecoule = 0.0;
                    g_en_attract = false;
                }
            }
        }
        if (g_video_visible) {
            if (!g_video.avancer(dt)) {
                // Fin de la demonstration : MoveNext, puis on recommence.
                arreter_video();
                suivant();
                g_ecoule = g_attract;        // enchaine sans attendre 30 s
                g_en_attract = false;
            }
        }
        break;

    case Etat::Lancement:
        g_anim += dt;
        if (g_anim >= 0.45) {
            const catalogue::Jeu& j = g_icones[g_index].jeu;
            std::wstring quoi;
            if (catalogue::lancer(j, quoi)) {
                message(L"Lancement de " + j.titre);
                // Le jeu prend la main : on s'efface.
                ShowWindow(g_fenetre, SW_MINIMIZE);
            } else {
                // bootApplication = false, le mode que SEGA a laisse : on
                // joue l'animation et on revient, sans rien demarrer.
                message(L"MODE VITRINE   " + j.titre +
                        L"   (aucun executable dans son dossier)");
            }
            g_etat = Etat::Retour;
            g_anim = 0.0;
        }
        break;

    case Etat::Retour:
        g_anim += dt;
        if (g_anim >= 0.45) { g_etat = Etat::Choix; g_ecoule = 0.0; }
        break;
    }
}

// ---------------------------------------------------------------------------
// Les entrees
// ---------------------------------------------------------------------------
void basculer_plein_ecran() {
    g_plein_ecran = !g_plein_ecran;
    if (g_plein_ecran) {
        GetWindowRect(g_fenetre, &g_avant_plein);
        MONITORINFO mi = {sizeof(mi)};
        GetMonitorInfoW(MonitorFromWindow(g_fenetre, MONITOR_DEFAULTTONEAREST),
                        &mi);
        SetWindowLongPtrW(g_fenetre, GWL_STYLE, WS_POPUP | WS_VISIBLE);
        SetWindowPos(g_fenetre, HWND_TOP, mi.rcMonitor.left, mi.rcMonitor.top,
                     mi.rcMonitor.right - mi.rcMonitor.left,
                     mi.rcMonitor.bottom - mi.rcMonitor.top, SWP_FRAMECHANGED);
    } else {
        SetWindowLongPtrW(g_fenetre, GWL_STYLE,
                          WS_OVERLAPPEDWINDOW | WS_VISIBLE);
        SetWindowPos(g_fenetre, HWND_TOP, g_avant_plein.left, g_avant_plein.top,
                     g_avant_plein.right - g_avant_plein.left,
                     g_avant_plein.bottom - g_avant_plein.top, SWP_FRAMECHANGED);
    }
}

void manette() {
    if (!g_xinput) return;
    for (DWORD i = 0; i < 4; ++i) {
        XINPUT_STATE etat = {};
        if (g_xinput(i, &etat) != ERROR_SUCCESS) continue;
        WORD b = etat.Gamepad.wButtons;
        SHORT ax = etat.Gamepad.sThumbLX;
        int sens = (b & XINPUT_GAMEPAD_DPAD_RIGHT) || ax > 16000 ? 1
                 : (b & XINPUT_GAMEPAD_DPAD_LEFT) || ax < -16000 ? -1 : 0;
        int sens_avant = (g_boutons_avant & XINPUT_GAMEPAD_DPAD_RIGHT) ||
                          g_axe_avant > 16000 ? 1
                       : (g_boutons_avant & XINPUT_GAMEPAD_DPAD_LEFT) ||
                          g_axe_avant < -16000 ? -1 : 0;
        if (sens && sens != sens_avant) {
            entree_quelconque();
            if (sens > 0) aller_droite(); else aller_gauche();
        }
        bool a = (b & XINPUT_GAMEPAD_A) != 0;
        bool a_avant = (g_boutons_avant & XINPUT_GAMEPAD_A) != 0;
        if (a && !a_avant) { entree_quelconque(); demarrer(); }
        bool bb = (b & XINPUT_GAMEPAD_B) != 0;
        bool b_avant = (g_boutons_avant & XINPUT_GAMEPAD_B) != 0;
        if (bb && !b_avant) entree_quelconque();
        g_boutons_avant = b;
        g_axe_avant = ax;
        break;
    }
}

LRESULT CALLBACK proc(HWND h, UINT m, WPARAM w, LPARAM l) {
    switch (m) {
    case WM_SIZE:
        if (w != SIZE_MINIMIZED)
            rendu::redimensionner(LOWORD(l), HIWORD(l));
        return 0;
    case WM_KEYDOWN:
        entree_quelconque();
        switch (w) {
        case VK_LEFT:   aller_gauche(); break;
        case VK_RIGHT:  aller_droite(); break;
        case VK_RETURN:
        case VK_SPACE:  demarrer(); break;
        case VK_F5:     charger_catalogue();
                        message(L"Catalogue relu"); break;
        case VK_F11:    basculer_plein_ecran(); break;
        case VK_ESCAPE:
            if (g_plein_ecran) basculer_plein_ecran();
            else PostQuitMessage(0);
            break;
        }
        return 0;
    case WM_LBUTTONDOWN:
        entree_quelconque();
        return 0;
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }
    return DefWindowProcW(h, m, w, l);
}

std::wstring dossier_du_programme() {
    wchar_t chemin[MAX_PATH] = {};
    GetModuleFileNameW(nullptr, chemin, MAX_PATH);
    std::wstring s = chemin;
    size_t barre = s.find_last_of(L'\\');
    return (barre == std::wstring::npos) ? L"." : s.substr(0, barre);
}

} // namespace anonyme

// ---------------------------------------------------------------------------
int WINAPI wWinMain(HINSTANCE inst, HINSTANCE, LPWSTR ligne, int) {
    // Le dossier des jeux : `borne\jeux` a cote de l'executable, ou le
    // premier argument de la ligne de commande.
    g_dossier_jeux = dossier_du_programme() + L"\\jeux";
    if (ligne && *ligne) {
        std::wstring a = ligne;
        if (a.size() > 1 && a.front() == L'"' && a.back() == L'"')
            a = a.substr(1, a.size() - 2);
        if (!a.empty()) g_dossier_jeux = a;
    }

    WNDCLASSEXW wc = {sizeof(wc)};
    wc.lpfnWndProc = proc;
    wc.hInstance = inst;
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hbrBackground = (HBRUSH)GetStockObject(BLACK_BRUSH);
    wc.lpszClassName = L"BorneAPM3";
    RegisterClassExW(&wc);

    RECT r = {0, 0, 1280, 720};
    AdjustWindowRect(&r, WS_OVERLAPPEDWINDOW, FALSE);
    g_fenetre = CreateWindowExW(
        0, wc.lpszClassName, L"Borne", WS_OVERLAPPEDWINDOW | WS_VISIBLE,
        CW_USEDEFAULT, CW_USEDEFAULT, r.right - r.left, r.bottom - r.top,
        nullptr, nullptr, inst, nullptr);
    if (!g_fenetre) return 1;

    if (!rendu::ouvrir(g_fenetre)) {
        MessageBoxW(nullptr, L"Direct3D 11 n'a pas pu demarrer.",
                    L"Borne", MB_ICONERROR);
        return 1;
    }
    video_ouvrir_module();

    HMODULE xi = LoadLibraryW(L"xinput1_4.dll");
    if (!xi) xi = LoadLibraryW(L"xinput1_3.dll");
    if (!xi) xi = LoadLibraryW(L"xinput9_1_0.dll");
    if (xi) g_xinput = (PFN_XInputGetState)GetProcAddress(xi, "XInputGetState");

    g_txt_aide = rendu::graver_texte(
        L"← →  choisir        Entree  lancer        "
        L"F5  relire le catalogue        F11  plein ecran        "
        L"Echap  quitter", 24, false);
    g_txt_vide = rendu::graver_texte(
        L"Aucun jeu. Posez un dossier par jeu dans borne\\jeux "
        L"(voir borne\\LISEZ-MOI.txt)", 30, false);

    charger_catalogue();

    LARGE_INTEGER frequence, avant;
    QueryPerformanceFrequency(&frequence);
    QueryPerformanceCounter(&avant);

    MSG msg;
    bool tourne = true;
    while (tourne) {
        while (PeekMessageW(&msg, nullptr, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) { tourne = false; break; }
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
        if (!tourne) break;

        LARGE_INTEGER maintenant;
        QueryPerformanceCounter(&maintenant);
        double dt = (double)(maintenant.QuadPart - avant.QuadPart) /
                    (double)frequence.QuadPart;
        avant = maintenant;
        if (dt > 0.25) dt = 0.25;      // apres une pause, on ne rattrape pas

        manette();
        avancer(dt);
        dessiner();
    }

    liberer_icones();
    rendu::liberer(g_txt_aide);
    rendu::liberer(g_txt_vide);
    rendu::liberer(g_txt_message);
    g_video.fermer();
    video_fermer_module();
    rendu::fermer();
    return 0;
}

