112	
113	// Le meme calcul que Select() et que Awake() : on cherche la plus petite
114	// vitesse entiere telle que 1 + 2 + ... + n couvre la distance. C'est une
115	// somme triangulaire, et c'est ce qui fait qu'une icone s'arrete PILE au
116	// centre sans etre rattrapee par une interpolation.
117	float resoudre_vitesse(float distance) {
118	    float vitesse = DECEL;
119	    float parcouru = 0.0f;
120	    int garde = 100000;
121	    while (parcouru < distance && garde-- > 0) {
122	        parcouru += vitesse;
123	        vitesse += DECEL;
124	    }
125	    return vitesse;
126	}
