134	void selectionner(int cible) {
135	    if (g_icones.empty()) return;
136	    cible = std::max(0, std::min((int)g_icones.size() - 1, cible));
137	    float x = g_icones[cible].x;
138	    float v = resoudre_vitesse(std::fabs(x));
139	    g_vitesse = (x > 0.0f) ? -v : v;
140	    g_index = cible;
141	    g_en_mouvement = true;
142	}
143	
