152	            if (g_icones[choix].x < g_icones[i].x && g_icones[i].x <= 0.0f)
153	                choix = (int)i;
154	    } else {
155	        choix = (int)g_icones.size() - 1;
156	        for (size_t i = 0; i < g_icones.size(); ++i)
157	            if (g_icones[choix].x > g_icones[i].x && g_icones[i].x >= 0.0f)
158	                choix = (int)i;
159	    }
160	    return choix;
161	}
162	
163	// IntertialMove, ligne pour ligne.
164	void mouvement_inertiel() {
165	    if (g_icones.empty()) return;
