// ---------------------------------------------------------------------------
// SON -- mise en oeuvre. Voir son.h.
// ---------------------------------------------------------------------------
#include "son.h"
#include <windows.h>
#include <xaudio2.h>
#include <vector>

namespace son {
namespace {

IXAudio2* g_moteur = nullptr;
IXAudio2MasteringVoice* g_maitre = nullptr;
float g_volume = 0.55f;

struct Echantillon {
    WAVEFORMATEX format = {};
    std::vector<unsigned char> pcm;
    // Une voix par effet suffit : un clic recouvre le precedent, comme sur la
    // borne. Pas de melange a gerer, pas de file d'attente.
    IXAudio2SourceVoice* voix = nullptr;
    bool pret = false;
};

Echantillon g_sons[4];

// -- un lecteur de WAV, juste ce qu'il faut ---------------------------------
// On ne prend que du PCM non compresse : c'est ce que produit la conversion,
// et cela evite d'embarquer un decodeur pour rien.
bool lire_wav(const std::wstring& chemin, Echantillon& e) {
    HANDLE h = CreateFileW(chemin.c_str(), GENERIC_READ, FILE_SHARE_READ,
                           nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL,
                           nullptr);
    if (h == INVALID_HANDLE_VALUE) return false;
    LARGE_INTEGER taille;
    if (!GetFileSizeEx(h, &taille) || taille.QuadPart < 44 ||
        taille.QuadPart > (16 << 20)) {
        CloseHandle(h);
        return false;
    }
    std::vector<unsigned char> d((size_t)taille.QuadPart);
    DWORD lus = 0;
    ReadFile(h, d.data(), (DWORD)d.size(), &lus, nullptr);
    CloseHandle(h);
    if (lus < 44) return false;
    d.resize(lus);

    if (memcmp(d.data(), "RIFF", 4) || memcmp(d.data() + 8, "WAVE", 4))
        return false;

    bool a_format = false;
    size_t i = 12;
    while (i + 8 <= d.size()) {
        char id[5] = {};
        memcpy(id, &d[i], 4);
        unsigned int n = 0;
        memcpy(&n, &d[i + 4], 4);
        size_t corps = i + 8;
        if (corps + n > d.size()) n = (unsigned int)(d.size() - corps);

        if (!memcmp(id, "fmt ", 4) && n >= 16) {
            memcpy(&e.format, &d[corps], (n >= sizeof(WAVEFORMATEX))
                                              ? sizeof(WAVEFORMATEX) : n);
            e.format.cbSize = 0;
            if (e.format.wFormatTag != WAVE_FORMAT_PCM) return false;
            a_format = true;
        } else if (!memcmp(id, "data", 4)) {
            e.pcm.assign(d.begin() + corps, d.begin() + corps + n);
        }
        i = corps + n + (n & 1);          // les blocs sont alignes sur 2
    }
    return a_format && !e.pcm.empty();
}

const wchar_t* NOMS[4] = {L"curseur.wav", L"valider.wav", L"retour.wav",
                          L"demarrer.wav"};

} // namespace anonyme

bool ouvrir(const std::wstring& dossier) {
    // XAudio2 veut COM. rendu::ouvrir l'a deja initialise, mais on ne peut pas
    // en dependre : un second appel est sans effet et rend S_FALSE.
    CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    if (FAILED(XAudio2Create(&g_moteur, 0, XAUDIO2_DEFAULT_PROCESSOR)))
        return false;
    if (FAILED(g_moteur->CreateMasteringVoice(&g_maitre))) {
        g_moteur->Release();
        g_moteur = nullptr;
        return false;
    }
    for (int k = 0; k < 4; ++k) {
        Echantillon& e = g_sons[k];
        if (!lire_wav(dossier + L"\\" + NOMS[k], e)) continue;
        if (FAILED(g_moteur->CreateSourceVoice(&e.voix, &e.format)))
            continue;
        e.voix->SetVolume(g_volume);
        e.pret = true;
    }
    return true;
}

void fermer() {
    for (int k = 0; k < 4; ++k) {
        if (g_sons[k].voix) {
            g_sons[k].voix->Stop(0);
            g_sons[k].voix->DestroyVoice();
            g_sons[k].voix = nullptr;
        }
        g_sons[k].pret = false;
    }
    if (g_maitre) { g_maitre->DestroyVoice(); g_maitre = nullptr; }
    if (g_moteur) { g_moteur->Release(); g_moteur = nullptr; }
}

void jouer(Effet quoi) {
    int k = (int)quoi;
    if (k < 0 || k > 3) return;
    Echantillon& e = g_sons[k];
    if (!e.pret) return;

    // On repart du debut : le clic suivant recouvre le precedent.
    e.voix->Stop(0);
    e.voix->FlushSourceBuffers();

    XAUDIO2_BUFFER b = {};
    b.AudioBytes = (UINT32)e.pcm.size();
    b.pAudioData = e.pcm.data();
    b.Flags = XAUDIO2_END_OF_STREAM;
    if (SUCCEEDED(e.voix->SubmitSourceBuffer(&b)))
        e.voix->Start(0);
}

void volume(float v) {
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;
    g_volume = v;
    for (int k = 0; k < 4; ++k)
        if (g_sons[k].voix) g_sons[k].voix->SetVolume(g_volume);
}

} // namespace son

