1	// ---------------------------------------------------------------------------
2	// LA BORNE -- l'interface, en C++.
3	//
4	// Portage de l'ecran de choix des jeux de l'ALL.Net P-ras Multi version 3.
5	// Le carrousel et la machine a etats ne sont pas imites : ils sont TRANSCRITS
6	// depuis le code de SEGA, decompile dans analysis/apm3_source/ et decrit dans
7	// analysis/interface_apm3_code.md.
8	//
9	// Ce qui vient tel quel de `Apm.System.GameSelect.IconListCanvas` :
10	//
11	//     accel = -1        la deceleration, en pixels par trame et par trame
12	//     iconSize = 256    le cote d'une icone
13	//     gapSize = 16      l'ecart entre deux icones, donc un pas de 272
14	//     selectedIconRatio = 1.5    l'agrandissement de l'icone du centre
15	//     rangeOfMovement = 0.5      la butee, a 128 px
16	//     conditionSpeed             resolu comme dans Awake : 24
17	//
18	// Et le mouvement lui-meme -- Select, IntertialMove, AlignmentIcon, Sort,
19	// GetNextSelectIcon -- ligne pour ligne.
20	//
21	// Ce qui change, et c'est tout : la liste des jeux vient d'un DOSSIER et non
22	// du demon `amdaemon`. Rien d'autre n'a ete simplifie.
23	// ---------------------------------------------------------------------------
24	#include "rendu.h"
25	#include "catalogue.h"
26	#include "video.h"
27	#include "son.h"
28	#include <windows.h>
29	#include <xinput.h>
30	#include <algorithm>
31	#include <cmath>
32	#include <string>
33	#include <vector>
34	
35	// ---------------------------------------------------------------------------
36	// Les constantes de SEGA. Ne pas les ajuster a l'oeil : elles sont lues.
37	// ---------------------------------------------------------------------------
38	const float DECEL = 1.0f;         // |accel.x|
39	const float TAILLE_ICONE = 256.0f;
40	const float ECART = 16.0f;
41	const float PAS = TAILLE_ICONE + ECART;          // 272
42	const float RATIO_SELECTION = 1.5f;
43	const float PORTEE_MOUVEMENT = 0.5f;             // butee a 128 px
44	const float OMBRE_Z_CENTRE = -24.0f;
45	const float OMBRE_Z = -16.0f;
46	
47	// La borne tourne a 60 images par seconde, et `speed` est en pixels PAR
48	// TRAME. On avance donc la logique par pas fixes de 1/60 s, quelle que soit
49	// la cadence reelle de l'ecran : sinon le ressenti changerait avec le moniteur.
50	const double PAS_LOGIQUE = 1.0 / 60.0;
51	
52	// La mise en page, sur l'ecran de reference de 1920 x 1080.
53	const float BANDE_HAUT = 96.0f;
54	const float BANDE_BAS = 88.0f;
55	const float Y_ICONES = 500.0f;
56	const float Y_TITRE = 762.0f;
57	const float Y_SOUS = 818.0f;
58	const float Y_MESSAGE = 906.0f;
59	
60	const double ATTRACT_DEFAUT = 30.0;   // advertizeTime, en secondes
61	
62	// LE ROSE DE LA BORNE, mesure et non choisi : #EB407B est la couleur pleine
63	// des fleches et du bouton de lecture extraits des assets de SEGA. Le fond,
64	// lui, n'est PAS mesurable -- les textures de panneau sont des masques blancs
65	// teintes par un materiau, qui vit dans la scene Unity et non dans le code.
66	const rendu::Couleur ROSE = {0xEB / 255.0f, 0x40 / 255.0f, 0x7B / 255.0f, 1.0f};
67	
68	// ---------------------------------------------------------------------------
69	namespace {
70	
71	struct Icone {
72	    catalogue::Jeu jeu;
73	    rendu::Texture jaquette;
74	    rendu::Texture titre;
75	    rendu::Texture sous;
76	    float x = 0.0f;               // anchoredPosition.x
77	};
78	
79	std::vector<Icone> g_icones;
80	int g_index = 0;
81	float g_vitesse = 0.0f;
82	float g_condition_vitesse = 24.0f;
83	bool g_en_mouvement = false;
84	bool g_inertie = false;
85	
86	// L'etat de scene, transcrit de GameSelect.SceneManager.
87	enum class Etat { Choix, Lancement, Retour };
88	Etat g_etat = Etat::Choix;
89	double g_anim = 0.0;              // avancement de l'animation en cours
90	double g_ecoule = 0.0;            // elapsedTime
91	double g_attract = ATTRACT_DEFAUT;
92	bool g_en_attract = false;
93	std::wstring g_message;
94	double g_message_reste = 0.0;
95	
96	Video g_video;
97	bool g_video_visible = false;
98	
99	rendu::Texture g_txt_aide;
100	rendu::Texture g_txt_vide;
101	rendu::Texture g_txt_message;
102	std::wstring g_message_grave;
103	
104	// L'habillage, extrait des assets Unity de la borne par tools/apm_icones.py.
105	// Les fleches et le bouton de lecture sont ceux de SEGA, y compris leur rose.
106	rendu::Texture g_hab_gauche;
107	rendu::Texture g_hab_droite;
108	rendu::Texture g_hab_logo;
109	rendu::Texture g_hab_lecture;
110	
111	HWND g_fenetre = nullptr;
112	std::wstring g_dossier_jeux;
113	bool g_plein_ecran = false;
114	RECT g_avant_plein = {};
115	
116	// XInput est charge a la demande : ainsi le programme demarre meme si la DLL
117	// manque, et il n'y a rien a lier a la compilation.
118	typedef DWORD (WINAPI* PFN_XInputGetState)(DWORD, XINPUT_STATE*);
119	PFN_XInputGetState g_xinput = nullptr;
120	WORD g_boutons_avant = 0;
121	SHORT g_axe_avant = 0;
122	
123	// ---------------------------------------------------------------------------
124	// Le carrousel. Transcription de IconListCanvas.
125	// ---------------------------------------------------------------------------
126	
127	// Le meme calcul que Select() et que Awake() : on cherche la plus petite
128	// vitesse entiere telle que 1 + 2 + ... + n couvre la distance. C'est une
129	// somme triangulaire, et c'est ce qui fait qu'une icone s'arrete PILE au
130	// centre sans etre rattrapee par une interpolation.
131	float resoudre_vitesse(float distance) {
132	    float vitesse = DECEL;
133	    float parcouru = 0.0f;
134	    int garde = 100000;
135	    while (parcouru < distance && garde-- > 0) {
136	        parcouru += vitesse;
137	        vitesse += DECEL;
138	    }
139	    return vitesse;
140	}
141	
142	void aligner(int selection, float decalage = 0.0f) {
143	    for (size_t i = 0; i < g_icones.size(); ++i)
144	        g_icones[i].x = -PAS * (float)(selection - (int)i) + decalage;
145	    g_vitesse = 0.0f;
146	}
147	
148	void selectionner(int cible) {
149	    if (g_icones.empty()) return;
150	    cible = std::max(0, std::min((int)g_icones.size() - 1, cible));
151	    float x = g_icones[cible].x;
152	    float v = resoudre_vitesse(std::fabs(x));
153	    g_vitesse = (x > 0.0f) ? -v : v;
154	    g_index = cible;
155	    g_en_mouvement = true;
156	}
157	
158	// GetNextSelectIcon : selon le sens, l'icone la plus proche du centre du bon
159	// cote -- celle qui va y arriver.
160	int prochaine_selection() {
161	    if (g_icones.empty()) return 0;
162	    int choix;
163	    if (g_vitesse > 0.0f) {
164	        choix = 0;
165	        for (size_t i = 0; i < g_icones.size(); ++i)
166	            if (g_icones[choix].x < g_icones[i].x && g_icones[i].x <= 0.0f)
167	                choix = (int)i;
168	    } else {
169	        choix = (int)g_icones.size() - 1;
170	        for (size_t i = 0; i < g_icones.size(); ++i)
171	            if (g_icones[choix].x > g_icones[i].x && g_icones[i].x >= 0.0f)
172	                choix = (int)i;
173	    }
174	    return choix;
175	}
176	
177	// IntertialMove, ligne pour ligne.
178	void mouvement_inertiel() {
179	    if (g_icones.empty()) return;
180	    for (Icone& ic : g_icones) ic.x += g_vitesse;
181	
182	    float reste = std::fabs(g_vitesse) - DECEL;
183	    if (reste < 0.0f) g_vitesse = 0.0f;
