// Le bandeau du bas : les pictos de touches de la borne, puis leur sens.
// La borne montre ce qu'il faut presser, pas le nom des touches.
{
    const float YB = rendu::HAUTEUR_REF - BANDE_BAS * 0.5f;
    const float H_PICTO = 40.0f;
    const rendu::Couleur GRIS = {0.62f, 0.66f, 0.72f, 1.0f};
    struct Bloc { const rendu::Texture* a; const rendu::Texture* b;
                  const rendu::Texture* mot; };
    Bloc blocs[] = {
        {&g_hab_fleche_g, &g_hab_fleche_d, &g_txt_choisir},
        {&g_hab_bouton_a, nullptr, &g_txt_lancer},
        {&g_hab_bouton_b, nullptr, &g_txt_demo},
        {nullptr, nullptr, &g_txt_quitter},
    };
    // On mesure d'abord la largeur totale, pour centrer l'ensemble.
    float total = 0.0f;
    for (const Bloc& bl : blocs) {
        if (bl.a && bl.a->valide()) total += H_PICTO + 8.0f;
        if (bl.b && bl.b->valide()) total += H_PICTO + 8.0f;
        if (bl.mot && bl.mot->valide()) total += bl.mot->large + 46.0f;
    }
    float x = CX - total * 0.5f;
    for (const Bloc& bl : blocs) {
        const rendu::Texture* pictos[2] = {bl.a, bl.b};
        for (const rendu::Texture* p : pictos) {
            if (!p || !p->valide()) continue;
            rendu::quad(*p, x + H_PICTO * 0.5f, YB, H_PICTO, H_PICTO,
                        rendu::blanc());
            x += H_PICTO + 8.0f;
        }
        if (bl.mot && bl.mot->valide()) {
            rendu::quad(*bl.mot, x + bl.mot->large * 0.5f + 6.0f, YB,
                        (float)bl.mot->large, (float)bl.mot->haut, GRIS);
            x += bl.mot->large + 46.0f;
        }
    }
}

