        if (bl.b && bl.b->valide()) total += H_PICTO + 8.0f;
        if (bl.mot && bl.mot->valide()) total += bl.mot->large + 46.0f;
    }
    float x = CX - total * 0.5f;
    for (const Bloc& bl : blocs) {
        const rendu::Texture* pictos[2] = {bl.a, bl.b};
        for (const rendu::Texture* p : pictos) {
            if (!p || !p->valide()) continue;
            rendu::quad(*p, x + H_PICTO * 0.5f, YB, H_PICTO, H_PICTO,
                        rendu::blanc());
            x += H_PICTO + 8.0f;
        }
        if (bl.mot && bl.mot->valide()) {
            rendu::quad(*bl.mot, x + bl.mot->large * 0.5f + 6.0f, YB,
                        (float)bl.mot->large, (float)bl.mot->haut, GRIS);
            x += bl.mot->large + 46.0f;
        }
    }
}

