128	bool g_plein_ecran = false;
129	RECT g_avant_plein = {};
130	
131	// XInput est charge a la demande : ainsi le programme demarre meme si la DLL
132	// manque, et il n'y a rien a lier a la compilation.
133	typedef DWORD (WINAPI* PFN_XInputGetState)(DWORD, XINPUT_STATE*);
134	PFN_XInputGetState g_xinput = nullptr;
135	WORD g_boutons_avant = 0;
136	SHORT g_axe_avant = 0;
137	
138	// ---------------------------------------------------------------------------
139	// Le carrousel. Transcription de IconListCanvas.
140	// ---------------------------------------------------------------------------
141	
142	// Le meme calcul que Select() et que Awake() : on cherche la plus petite
143	// vitesse entiere telle que 1 + 2 + ... + n couvre la distance. C'est une
144	// somme triangulaire, et c'est ce qui fait qu'une icone s'arrete PILE au
145	// centre sans etre rattrapee par une interpolation.
146	float resoudre_vitesse(float distance) {
147	    float vitesse = DECEL;
148	    float parcouru = 0.0f;
149	    int garde = 100000;
150	    while (parcouru < distance && garde-- > 0) {
151	        parcouru += vitesse;
152	        vitesse += DECEL;
153	    }
154	    return vitesse;
155	}
156	
157	void aligner(int selection, float decalage = 0.0f) {
158	    for (size_t i = 0; i < g_icones.size(); ++i)
159	        g_icones[i].x = -PAS * (float)(selection - (int)i) + decalage;
160	    g_vitesse = 0.0f;
161	}
162	
163	void selectionner(int cible) {
164	    if (g_icones.empty()) return;
165	    cible = std::max(0, std::min((int)g_icones.size() - 1, cible));
166	    float x = g_icones[cible].x;
167	    float v = resoudre_vitesse(std::fabs(x));
168	    g_vitesse = (x > 0.0f) ? -v : v;
169	    g_index = cible;
170	    g_en_mouvement = true;
171	}
172	
173	// GetNextSelectIcon : selon le sens, l'icone la plus proche du centre du bon
174	// cote -- celle qui va y arriver.
175	int prochaine_selection() {
176	    if (g_icones.empty()) return 0;
177	    int choix;
178	    if (g_vitesse > 0.0f) {
179	        choix = 0;
180	        for (size_t i = 0; i < g_icones.size(); ++i)
181	            if (g_icones[choix].x < g_icones[i].x && g_icones[i].x <= 0.0f)
182	                choix = (int)i;
183	    } else {
184	        choix = (int)g_icones.size() - 1;
185	        for (size_t i = 0; i < g_icones.size(); ++i)
186	            if (g_icones[choix].x > g_icones[i].x && g_icones[i].x >= 0.0f)
187	                choix = (int)i;
188	    }
189	    return choix;
190	}
191	
192	// IntertialMove, ligne pour ligne.
193	void mouvement_inertiel() {
194	    if (g_icones.empty()) return;
195	    for (Icone& ic : g_icones) ic.x += g_vitesse;
196	
197	    float reste = std::fabs(g_vitesse) - DECEL;
