199	    else g_vitesse = (g_vitesse > 0.0f) ? reste : -reste;
200	
201	    if (std::fabs(g_vitesse) >= std::fabs(g_condition_vitesse)) {
202	        // Encore lance : on ne laisse pas la liste sortir de ses bornes.
203	        float butee = TAILLE_ICONE * PORTEE_MOUVEMENT;      // 128
