// ---- LA RESOLUTION REELLE, ET LA PIXELLISATION -----------------------
// L'ecran de Frederic est a 250 %. Un programme qui ne se declare pas
// conscient de cette mise a l'echelle recoit une fenetre de 1280 x 720
// pixels LOGIQUES, dessine dedans, et Windows agrandit le resultat de
// 2,5 fois : tout est flou. En se declarant conscient par moniteur, la
// fenetre recoit ses pixels PHYSIQUES et le rendu est net.
//
// Charge a la volee : ces fonctions n'existent pas sur les vieux Windows,
// et on ne veut pas d'une dependance de liaison pour un reglage.
{
    HMODULE u = GetModuleHandleW(L"user32.dll");
    typedef BOOL (WINAPI * PFN_ctx)(HANDLE);
    PFN_ctx par_moniteur = u ? (PFN_ctx)GetProcAddress(
        u, "SetProcessDpiAwarenessContext") : nullptr;
    // -4 = DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2
    if (!par_moniteur || !par_moniteur((HANDLE)(INT_PTR)-4)) {
        typedef BOOL (WINAPI * PFN_vieux)(void);
        PFN_vieux vieux = u ? (PFN_vieux)GetProcAddress(
            u, "SetProcessDPIAware") : nullptr;
        if (vieux) vieux();
    }
}

WNDCLASSEXW wc = {sizeof(wc)};

