// BANC D'ESSAI DE LA VIDEO -- console, pour voir le VRAI code d'erreur.
//
// La borne se contente d'un message a l'ecran ; ici on veut le HRESULT de
// chaque etape, sinon on tatonne.
//
//     essai_video.exe "C:\...\demo.mp4"
// ---------------------------------------------------------------------------
#include <windows.h>
#include <mfapi.h>
#include <mfidl.h>
#include <mfreadwrite.h>
#include <mferror.h>
#include <stdio.h>

static void dire(const char* quoi, HRESULT hr) {
    printf("  %-46s 0x%08lX %s\n", quoi, (unsigned long)hr,
           SUCCEEDED(hr) ? "OK" : "ECHEC");
}

int wmain(int argc, wchar_t** argv) {
    if (argc < 2) { printf("usage : essai_video.exe <fichier>\n"); return 1; }

    HRESULT hr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    dire("CoInitializeEx(MULTITHREADED)", hr);
    hr = MFStartup(MF_VERSION, MFSTARTUP_FULL);
    dire("MFStartup(FULL)", hr);
    if (FAILED(hr)) return 1;

    // On essaie les trois combinaisons d'attributs, pour savoir laquelle
    // Media Foundation accepte reellement.
    const char* noms[3] = {"aucun traitement d'image",
                           "ENABLE_VIDEO_PROCESSING seul",
                           "ENABLE_ADVANCED_VIDEO_PROCESSING seul"};
    for (int essai = 0; essai < 3; ++essai) {
        printf("\n--- %s ---\n", noms[essai]);
        IMFAttributes* at = nullptr;
        hr = MFCreateAttributes(&at, 2);
        if (essai == 1) at->SetUINT32(MF_SOURCE_READER_ENABLE_VIDEO_PROCESSING, TRUE);
        if (essai == 2) at->SetUINT32(MF_SOURCE_READER_ENABLE_ADVANCED_VIDEO_PROCESSING, TRUE);

        IMFSourceReader* lec = nullptr;
        hr = MFCreateSourceReaderFromURL(argv[1], at, &lec);
        at->Release();
        dire("MFCreateSourceReaderFromURL", hr);
        if (FAILED(hr)) continue;

        lec->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS, FALSE);
        hr = lec->SetStreamSelection((DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, TRUE);
        dire("SetStreamSelection(video)", hr);

        // Ce que la source propose d'elle-meme.
        IMFMediaType* natif = nullptr;
        if (SUCCEEDED(lec->GetNativeMediaType(
                (DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0, &natif))) {
            GUID sous = {};
            natif->GetGUID(MF_MT_SUBTYPE, &sous);
            UINT32 w = 0, h = 0;
            MFGetAttributeSize(natif, MF_MT_FRAME_SIZE, &w, &h);
            printf("  natif : %ux%u  sous-type %08lX-%04X-%04X\n", w, h,
                   (unsigned long)sous.Data1, sous.Data2, sous.Data3);
            natif->Release();
        }

        IMFMediaType* voulu = nullptr;
        MFCreateMediaType(&voulu);
        voulu->SetGUID(MF_MT_MAJOR_TYPE, MFMediaType_Video);
        voulu->SetGUID(MF_MT_SUBTYPE, MFVideoFormat_RGB32);
        hr = lec->SetCurrentMediaType(
            (DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, nullptr, voulu);
        voulu->Release();
        dire("SetCurrentMediaType(RGB32)", hr);

        if (SUCCEEDED(hr)) {
            DWORD flux = 0, dr = 0; LONGLONG date = 0; IMFSample* ech = nullptr;
            hr = lec->ReadSample((DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0,
                                 &flux, &dr, &date, &ech);
            dire("ReadSample", hr);
            if (ech) { printf("  une trame lue\n"); ech->Release(); }
        }
        lec->Release();
    }
    MFShutdown();
    return 0;
}

