// ---------------------------------------------------------------------------
// VIDEO -- mise en oeuvre. Voir video.h.
// ---------------------------------------------------------------------------
#include "video.h"
#include <windows.h>
#include <mfapi.h>
#include <mfidl.h>
#include <mfreadwrite.h>
#include <mferror.h>
#include <vector>

namespace {
bool g_module_pret = false;

// Media Foundation compte en unites de 100 nanosecondes.
const double CENT_NS = 10000000.0;
}

bool video_ouvrir_module() {
    if (g_module_pret) return true;
    // FULL et non LITE : le mode allege n'installe pas tout le resolveur de
    // sources, et l'ouverture d'un .mp4 par URL en depend.
    if (FAILED(MFStartup(MF_VERSION, MFSTARTUP_FULL))) return false;
    g_module_pret = true;
    return true;
}

void video_fermer_module() {
    if (!g_module_pret) return;
    MFShutdown();
    g_module_pret = false;
}

Video::~Video() { fermer(); }

bool Video::ouvrir(const std::wstring& chemin) {
    fermer();
    if (!g_module_pret || chemin.empty()) return false;

    IMFAttributes* attributs = nullptr;
    if (FAILED(MFCreateAttributes(&attributs, 2))) return false;
    // Sans cela, le lecteur refuse tout ce qui n'est pas deja en RGB.
    //
    // UN SEUL des deux attributs, jamais les deux. Les poser ensemble fait
    // echouer SetCurrentMediaType avec MF_E_INVALIDMEDIATYPE (0xC00D36B4),
    // et rien ne le dit a la creation : la video ne s'ouvre simplement pas.
    // Mesure par borne/src/essai_video.cpp, qui essaie les trois cas.
    attributs->SetUINT32(MF_SOURCE_READER_ENABLE_VIDEO_PROCESSING, TRUE);

    HRESULT hr = MFCreateSourceReaderFromURL(chemin.c_str(), attributs,
                                             &lecteur_);
    attributs->Release();
    if (FAILED(hr) || !lecteur_) { lecteur_ = nullptr; return false; }

    // On ne veut que l'image : le son est coupe (voir video.h).
    lecteur_->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS, FALSE);
    lecteur_->SetStreamSelection((DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM,
                                 TRUE);

    IMFMediaType* voulu = nullptr;
    if (FAILED(MFCreateMediaType(&voulu))) { fermer(); return false; }
    voulu->SetGUID(MF_MT_MAJOR_TYPE, MFMediaType_Video);
    voulu->SetGUID(MF_MT_SUBTYPE, MFVideoFormat_RGB32);
    hr = lecteur_->SetCurrentMediaType(
        (DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, nullptr, voulu);
    voulu->Release();
    if (FAILED(hr)) { fermer(); return false; }

    IMFMediaType* obtenu = nullptr;
    if (FAILED(lecteur_->GetCurrentMediaType(
            (DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, &obtenu))) {
        fermer(); return false;
    }
    UINT32 w = 0, h = 0;
    MFGetAttributeSize(obtenu, MF_MT_FRAME_SIZE, &w, &h);
    INT32 pas = 0;
    if (FAILED(obtenu->GetUINT32(MF_MT_DEFAULT_STRIDE, (UINT32*)&pas)) ||
        pas == 0) {
        // Absent : on le calcule, et RGB32 est alors renverse (bas en haut).
        LONG calcule = 0;
        MFGetStrideForBitmapInfoHeader(MFVideoFormat_RGB32.Data1, w, &calcule);
        pas = (INT32)calcule;
    }
    obtenu->Release();

    if (w == 0 || h == 0) { fermer(); return false; }
    large_ = (int)w;
    haut_ = (int)h;
    pas_ = (int)pas;
    texture_ = rendu::creer_dynamique(large_, haut_);
    if (!texture_.valide()) { fermer(); return false; }

    horloge_ = 0.0;
    prochaine_ = 0.0;
    finie_ = false;
    return true;
}

void Video::fermer() {
    if (lecteur_) { lecteur_->Release(); lecteur_ = nullptr; }
    rendu::liberer(texture_);
    large_ = haut_ = pas_ = 0;
    horloge_ = prochaine_ = 0.0;
    finie_ = false;
}

void Video::reprendre_au_debut() {
    if (!lecteur_) return;
    PROPVARIANT zero;
    PropVariantInit(&zero);
    zero.vt = VT_I8;
    zero.hVal.QuadPart = 0;
    lecteur_->SetCurrentPosition(GUID_NULL, zero);
    PropVariantClear(&zero);
    horloge_ = 0.0;
    prochaine_ = 0.0;
    finie_ = false;
}

bool Video::avancer(double dt) {
    if (!lecteur_ || finie_) return false;
    horloge_ += dt;

    // On ne decode que ce qu'il faut : tant que la trame suivante est dans le
    // passe, on la lit. Une trame par tour suffit a 60 Hz pour une video a 30.
    int garde = 4;
    while (horloge_ >= prochaine_ && garde-- > 0) {
        DWORD flux = 0, drapeaux = 0;
        LONGLONG date = 0;
        IMFSample* echantillon = nullptr;
        HRESULT hr = lecteur_->ReadSample(
            (DWORD)MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0, &flux, &drapeaux,
            &date, &echantillon);
        if (FAILED(hr)) { finie_ = true; return false; }

        if (drapeaux & MF_SOURCE_READERF_ENDOFSTREAM) {
            if (echantillon) echantillon->Release();
            if (boucler) { reprendre_au_debut(); continue; }
            finie_ = true;
            return false;
        }
        if (!echantillon) break;          // rien de pret, on retentera

        LONGLONG duree = 0;
        echantillon->GetSampleDuration(&duree);
        prochaine_ = (double)date / CENT_NS +
                     (duree > 0 ? (double)duree / CENT_NS : 1.0 / 30.0);

        IMFMediaBuffer* tampon = nullptr;
        if (SUCCEEDED(echantillon->ConvertToContiguousBuffer(&tampon))) {
            BYTE* octets = nullptr;
            DWORD longueur = 0;
            if (SUCCEEDED(tampon->Lock(&octets, nullptr, &longueur))) {
                if (pas_ >= 0) {
                    rendu::ecrire_dynamique(texture_, octets, pas_);
                } else {
                    // Image renversee : on la remet a l'endroit ligne a ligne.
                    int p = -pas_;
                    std::vector<unsigned char> droite((size_t)p * haut_);
                    for (int y = 0; y < haut_; ++y)
                        memcpy(&droite[(size_t)y * p],
                               octets + (size_t)(haut_ - 1 - y) * p, p);
                    rendu::ecrire_dynamique(texture_, droite.data(), p);
                }
                tampon->Unlock();
            }
            tampon->Release();
        }
        echantillon->Release();
    }
    return true;
}

