namespace {
// XAudio2 ne copie pas les octets qu'on lui soumet : il faut les garder
// vivants jusqu'a ce qu'il les ait joues. On tient donc une file, et on ne
// rend un morceau que lorsque la voix n'en a plus autant en attente.
struct File {
    std::deque<std::vector<unsigned char>> morceaux;
};
} // namespace anonyme

Flux::~Flux() { fermer(); }

bool Flux::ouvrir(int voies, int frequence, int bits) {
    fermer();
    if (!g_moteur || voies < 1 || frequence < 1) return false;
    WAVEFORMATEX f = {};
    f.wFormatTag = WAVE_FORMAT_PCM;
    f.nChannels = (WORD)voies;
    f.nSamplesPerSec = (DWORD)frequence;
    f.wBitsPerSample = (WORD)bits;
    f.nBlockAlign = (WORD)(voies * bits / 8);
    f.nAvgBytesPerSec = f.nSamplesPerSec * f.nBlockAlign;
    if (FAILED(g_moteur->CreateSourceVoice(&voix_, &f))) {
        voix_ = nullptr;
        return false;
    }
    morceaux_ = new File();
    voix_->SetVolume(muet_ ? 0.0f : 1.0f);
    voix_->Start(0);
    return true;
}

void Flux::pousser(const void* pcm, unsigned int octets) {
    if (!voix_ || !pcm || !octets) return;
    File* f = (File*)morceaux_;

    // On rend d'abord ce que la voix a fini de lire.
    XAUDIO2_VOICE_STATE etat = {};
    voix_->GetState(&etat);
    while (f->morceaux.size() > etat.BuffersQueued)
        f->morceaux.pop_front();

    f->morceaux.emplace_back((const unsigned char*)pcm,
                             (const unsigned char*)pcm + octets);
    XAUDIO2_BUFFER b = {};
    b.AudioBytes = octets;
    b.pAudioData = f->morceaux.back().data();
    voix_->SubmitSourceBuffer(&b);
}

void Flux::muet(bool oui) {
    muet_ = oui;
    if (voix_) voix_->SetVolume(oui ? 0.0f : 1.0f);
}

void Flux::fermer() {
    if (voix_) {
        voix_->Stop(0);
        voix_->FlushSourceBuffers();
        voix_->DestroyVoice();
        voix_ = nullptr;
    }
    delete (File*)morceaux_;
    morceaux_ = nullptr;
}

void volume(float v) {
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;
    g_volume = v;
    for (int k = 0; k < 4; ++k)
        if (g_sons[k].voix) g_sons[k].voix->SetVolume(g_volume);
}

