} // namespace anonyme

bool ouvrir(const std::wstring& dossier) {
    // XAudio2 veut COM. rendu::ouvrir l'a deja initialise, mais on ne peut pas
    // en dependre : un second appel est sans effet et rend S_FALSE.
    CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    if (FAILED(XAudio2Create(&g_moteur, 0, XAUDIO2_DEFAULT_PROCESSOR)))
        return false;
    if (FAILED(g_moteur->CreateMasteringVoice(&g_maitre))) {
        g_moteur->Release();
        g_moteur = nullptr;
        return false;
    }
    for (int k = 0; k < 4; ++k) {
        Echantillon& e = g_sons[k];
        if (!lire_wav(dossier + L"\\" + NOMS[k], e)) continue;
        if (FAILED(g_moteur->CreateSourceVoice(&e.voix, &e.format)))
            continue;
        e.voix->SetVolume(g_volume);
        e.pret = true;
    }
    return true;
}

void fermer() {
    for (int k = 0; k < 4; ++k) {
        if (g_sons[k].voix) {
            g_sons[k].voix->Stop(0);
            g_sons[k].voix->DestroyVoice();
            g_sons[k].voix = nullptr;
        }
        g_sons[k].pret = false;
    }
    if (g_maitre) { g_maitre->DestroyVoice(); g_maitre = nullptr; }
    if (g_moteur) { g_moteur->Release(); g_moteur = nullptr; }
}

void jouer(Effet quoi) {
    int k = (int)quoi;
    if (k < 0 || k > 3) return;
    Echantillon& e = g_sons[k];
    if (!e.pret) return;

    // On repart du debut : le clic suivant recouvre le precedent.
    e.voix->Stop(0);
    e.voix->FlushSourceBuffers();

    XAUDIO2_BUFFER b = {};
    b.AudioBytes = (UINT32)e.pcm.size();
    b.pAudioData = e.pcm.data();
    b.Flags = XAUDIO2_END_OF_STREAM;
    if (SUCCEEDED(e.voix->SubmitSourceBuffer(&b)))
        e.voix->Start(0);
}

// ---------------------------------------------------------------------------
// Le flux, pour la bande son des videos
// ---------------------------------------------------------------------------
namespace {
// XAudio2 ne copie pas les octets qu'on lui soumet : il faut les garder
// vivants jusqu'a ce qu'il les ait joues. On tient donc une file, et on ne
// rend un morceau que lorsque la voix n'en a plus autant en attente.
struct File {
    std::deque<std::vector<unsigned char>> morceaux;
};
} // namespace anonyme

Flux::~Flux() { fermer(); }

bool Flux::ouvrir(int voies, int frequence, int bits) {
    fermer();
    if (!g_moteur || voies < 1 || frequence < 1) return false;
    WAVEFORMATEX f = {};
    f.wFormatTag = WAVE_FORMAT_PCM;
    f.nChannels = (WORD)voies;
    f.nSamplesPerSec = (DWORD)frequence;
    f.wBitsPerSample = (WORD)bits;
    f.nBlockAlign = (WORD)(voies * bits / 8);
    f.nAvgBytesPerSec = f.nSamplesPerSec * f.nBlockAlign;
    if (FAILED(g_moteur->CreateSourceVoice(&voix_, &f))) {
        voix_ = nullptr;
        return false;
    }
    morceaux_ = new File();
    voix_->SetVolume(muet_ ? 0.0f : 1.0f);
    voix_->Start(0);
    return true;
}

void Flux::pousser(const void* pcm, unsigned int octets) {
    if (!voix_ || !pcm || !octets) return;
    File* f = (File*)morceaux_;

    // On rend d'abord ce que la voix a fini de lire.
    XAUDIO2_VOICE_STATE etat = {};
    voix_->GetState(&etat);
    while (f->morceaux.size() > etat.BuffersQueued)
        f->morceaux.pop_front();

    f->morceaux.emplace_back((const unsigned char*)pcm,
                             (const unsigned char*)pcm + octets);
    XAUDIO2_BUFFER b = {};
    b.AudioBytes = octets;
    b.pAudioData = f->morceaux.back().data();
    voix_->SubmitSourceBuffer(&b);
}

void Flux::muet(bool oui) {
    muet_ = oui;
    if (voix_) voix_->SetVolume(oui ? 0.0f : 1.0f);
}

void Flux::fermer() {
    if (voix_) {
        voix_->Stop(0);
        voix_->FlushSourceBuffers();
        voix_->DestroyVoice();
        voix_ = nullptr;
    }
    delete (File*)morceaux_;
    morceaux_ = nullptr;
}

void volume(float v) {
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;
    g_volume = v;
    for (int k = 0; k < 4; ++k)
        if (g_sons[k].voix) g_sons[k].voix->SetVolume(g_volume);
}

} // namespace son

