                    droite_.resize((size_t)p * haut_);
                for (int y = 0; y < haut_; ++y) {
                    const unsigned char* src =
                        octets + (size_t)(pas_ >= 0 ? y : haut_ - 1 - y) * p;
                    unsigned char* dst = &droite_[(size_t)y * p];
                    memcpy(dst, src, p);
                    for (int x = 3; x < large_ * 4; x += 4) dst[x] = 255;
                }
                rendu::ecrire_dynamique(texture_, droite_.data(), p);
                tampon->Unlock();
            }
            tampon->Release();
        }
        echantillon->Release();
    }
    return true;
}

