// ---------------------------------------------------------------------------
// SON -- XAudio2, le moteur audio de Windows.
//
// Rien a installer, rien a livrer : XAudio2 est dans Windows depuis la 8.
//
// LES BRUITAGES SONT CEUX DE LA BORNE. Ils dormaient dans
// `Apmv3System_Data/resources.resource`, en quatre banques FSB5 codees en
// Vorbis, sans aucun nom -- Unity n'ecrit pas les noms de type dans un build
// de sortie. `tools/apm_ui_sons.py` les sort ; ils sont ensuite convertis en
// WAV dans `borne/habillage/sons/`.
//
// A QUOI CHACUN SERT, EN REVANCHE, N'EST PAS ECRIT : rien dans les donnees ne
// dit lequel des quatre est le curseur et lequel la validation. Le classement
// retenu suit leur duree, du plus bref au plus long. Pour en echanger deux,
// il suffit de renommer les fichiers : ils sont charges par leur nom.
// ---------------------------------------------------------------------------
#pragma once
#include <string>

namespace son {

enum class Effet { Curseur, Valider, Retour, Demarrer };

// Ouvre XAudio2 et lit les quatre WAV du dossier donne. Rend false si le
// moteur audio est indisponible ; l'interface doit alors tourner en silence,
// pas s'arreter.
bool ouvrir(const std::wstring& dossier_sons);
void fermer();

void jouer(Effet quoi);
void volume(float v);          // 0 a 1

// ---------------------------------------------------------------------------
// UN FLUX -- pour la bande son des videos de demonstration.
//
// Un bruitage tient en memoire d'un bloc ; la piste d'une video arrive par
// morceaux, au fil du decodage. D'ou cette seconde voix, alimentee au fur et
// a mesure. Les morceaux deja joues sont recycles a chaque poussee : XAudio2
// lit directement dans NOTRE memoire, il ne la copie pas.
//
// La borne, elle, coupe le son de la demonstration pendant l'attract
// (`EnableAdvertizeSound`). On garde ce comportement : muet en attract,
// sonore quand c'est l'utilisateur qui demande la demo.
// ---------------------------------------------------------------------------
class Flux {
public:
    ~Flux();
    bool ouvrir(int voies, int frequence, int bits);
    void pousser(const void* pcm, unsigned int octets);
    void fermer();
    void muet(bool oui);
    bool ouvert() const { return voix_ != nullptr; }
    int en_attente() const;        // morceaux pas encore joues

private:
    struct IXAudio2SourceVoice* voix_ = nullptr;
    void* morceaux_ = nullptr;          // une file, cachee ici
    bool muet_ = false;
};

} // namespace son

