28	// -- un lecteur de WAV, juste ce qu'il faut ---------------------------------
29	// On ne prend que du PCM non compresse : c'est ce que produit la conversion,
30	// et cela evite d'embarquer un decodeur pour rien.
31	bool lire_wav(const std::wstring& chemin, Echantillon& e) {
32	    HANDLE h = CreateFileW(chemin.c_str(), GENERIC_READ, FILE_SHARE_READ,
33	                           nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL,
34	                           nullptr);
35	    if (h == INVALID_HANDLE_VALUE) return false;
36	    LARGE_INTEGER taille;
37	    if (!GetFileSizeEx(h, &taille) || taille.QuadPart < 44 ||
38	        taille.QuadPart > (16 << 20)) {
39	        CloseHandle(h);
40	        return false;
41	    }
42	    std::vector<unsigned char> d((size_t)taille.QuadPart);
43	    DWORD lus = 0;
44	    ReadFile(h, d.data(), (DWORD)d.size(), &lus, nullptr);
45	    CloseHandle(h);
46	    if (lus < 44) return false;
47	    d.resize(lus);
48	
49	    if (memcmp(d.data(), "RIFF", 4) || memcmp(d.data() + 8, "WAVE", 4))
50	        return false;
51	
52	    bool a_format = false;
53	    size_t i = 12;
54	    while (i + 8 <= d.size()) {
55	        char id[5] = {};
56	        memcpy(id, &d[i], 4);
57	        unsigned int n = 0;
58	        memcpy(&n, &d[i + 4], 4);
59	        size_t corps = i + 8;
60	        if (corps + n > d.size()) n = (unsigned int)(d.size() - corps);
61	
62	        if (!memcmp(id, "fmt ", 4) && n >= 16) {
63	            memcpy(&e.format, &d[corps], (n >= sizeof(WAVEFORMATEX))
64	                                              ? sizeof(WAVEFORMATEX) : n);
65	            e.format.cbSize = 0;
66	            if (e.format.wFormatTag != WAVE_FORMAT_PCM) return false;
67	            a_format = true;
68	        } else if (!memcmp(id, "data", 4)) {
69	            e.pcm.assign(d.begin() + corps, d.begin() + corps + n);
70	        }
71	        i = corps + n + (n & 1);          // les blocs sont alignes sur 2
72	    }
73	    return a_format && !e.pcm.empty();
74	}
75	
76	const wchar_t* NOMS[4] = {L"curseur.wav", L"valider.wav", L"retour.wav",
77	                          L"demarrer.wav"};
