95	        if (FAILED(g_moteur->CreateSourceVoice(&e.voix, &e.format)))
96	            continue;
97	        e.voix->SetVolume(g_volume);
98	        e.pret = true;
99	    }
100	    return true;
101	}
102	
103	void fermer() {
104	    for (int k = 0; k < 4; ++k) {
105	        if (g_sons[k].voix) {
106	            g_sons[k].voix->Stop(0);
107	            g_sons[k].voix->DestroyVoice();
108	            g_sons[k].voix = nullptr;
109	        }
