137	namespace {
138	// XAudio2 ne copie pas les octets qu'on lui soumet : il faut les garder
139	// vivants jusqu'a ce qu'il les ait joues. On tient donc une file, et on ne
140	// rend un morceau que lorsque la voix n'en a plus autant en attente.
141	struct File {
142	    std::deque<std::vector<unsigned char>> morceaux;
143	};
