148	bool Flux::ouvrir(int voies, int frequence, int bits) {
149	    fermer();
150	    if (!g_moteur || voies < 1 || frequence < 1) return false;
151	    WAVEFORMATEX f = {};
152	    f.wFormatTag = WAVE_FORMAT_PCM;
153	    f.nChannels = (WORD)voies;
154	    f.nSamplesPerSec = (DWORD)frequence;
155	    f.wBitsPerSample = (WORD)bits;
156	    f.nBlockAlign = (WORD)(voies * bits / 8);
157	    f.nAvgBytesPerSec = f.nSamplesPerSec * f.nBlockAlign;
158	    if (FAILED(g_moteur->CreateSourceVoice(&voix_, &f))) {
159	        voix_ = nullptr;
160	        return false;
161	    }
162	    morceaux_ = new File();
163	    voix_->SetVolume(muet_ ? 0.0f : 1.0f);
164	    voix_->Start(0);
165	    return true;
166	}
