168	void Flux::pousser(const void* pcm, unsigned int octets) {
169	    if (!voix_ || !pcm || !octets) return;
170	    File* f = (File*)morceaux_;
171	
172	    // On rend d'abord ce que la voix a fini de lire.
173	    XAUDIO2_VOICE_STATE etat = {};
174	    voix_->GetState(&etat);
175	    while (f->morceaux.size() > etat.BuffersQueued)
176	        f->morceaux.pop_front();
177	
178	    f->morceaux.emplace_back((const unsigned char*)pcm,
179	                             (const unsigned char*)pcm + octets);
180	    XAUDIO2_BUFFER b = {};
181	    b.AudioBytes = octets;
182	    b.pAudioData = f->morceaux.back().data();
183	    voix_->SubmitSourceBuffer(&b);
184	}
185	
186	int Flux::en_attente() const {
187	    if (!voix_) return 0;
188	    XAUDIO2_VOICE_STATE etat = {};
189	    voix_->GetState(&etat);
190	    return (int)etat.BuffersQueued;
191	}
192	
193	void Flux::muet(bool oui) {
194	    muet_ = oui;
195	    if (voix_) voix_->SetVolume(oui ? 0.0f : 1.0f);
196	}
