198	void Flux::fermer() {
199	    if (voix_) {
200	        voix_->Stop(0);
201	        voix_->FlushSourceBuffers();
202	        voix_->DestroyVoice();
203	        voix_ = nullptr;
204	    }
205	    delete (File*)morceaux_;
206	    morceaux_ = nullptr;
207	}
